function onForm(id,run){$(id).addEventListener('submit',event=>{event.preventDefault();guard(()=>run(event));});}
for(const form of document.querySelectorAll('form')){for(const event of ['input','change'])form.addEventListener(event,()=>guard(()=>retainForm(form.id)));}
$('operator-name').addEventListener('input',()=>guard(()=>put('drafts',key('operator'),$('operator-name').value)));
$('refresh-workspace').addEventListener('click',()=>guard(async()=>{await retainAllForms();await refresh();}));
$('export-select').addEventListener('change',()=>guard(()=>selectExport($('export-select').value)));
$('returned-file').addEventListener('change',()=>guard(chooseFile));
$('document-select').addEventListener('change',()=>guard(()=>retainForm('capture-form')));
$('inspect-prepared').addEventListener('click',()=>guard(preparedPage));
$('prepared-previous').addEventListener('click',()=>guard(async()=>{S.preparedOffset=Math.max(0,S.preparedOffset-25);await preparedPage();}));
$('prepared-next').addEventListener('click',()=>guard(async()=>{S.preparedOffset+=25;await preparedPage();}));
$('source-previous').addEventListener('click',()=>guard(async()=>{S.sourceOffset=Math.max(0,S.sourceOffset-25);await sourcePage();}));
$('source-next').addEventListener('click',()=>guard(async()=>{S.sourceOffset+=25;await sourcePage();}));
