$('add-status').addEventListener('click',()=>guard(async()=>{statusPair();await retainForm('mapping-form');}));
$('read-statuses').addEventListener('click',()=>guard(()=>readStatuses(false)));
$('more-statuses').addEventListener('click',()=>guard(()=>readStatuses(true)));
$('compare-amounts').addEventListener('change',()=>show('amount-fields',$('compare-amounts').checked));
$('row-family').addEventListener('change',()=>guard(async()=>{S.rowOffset=0;rowFilters();await rowPage();}));
$('search-rows').addEventListener('click',()=>guard(async()=>{S.rowOffset=0;await rowPage();}));
$('row-query').addEventListener('keydown',event=>{if(event.key==='Enter'){event.preventDefault();guard(async()=>{S.rowOffset=0;await rowPage();});}});
$('row-previous').addEventListener('click',()=>guard(async()=>{S.rowOffset=Math.max(0,S.rowOffset-50);await rowPage();}));
$('row-next').addEventListener('click',()=>guard(async()=>{if(S.rowOffset+50<S.rowTotal){S.rowOffset+=50;await rowPage();}}));
$('download-row').addEventListener('click',()=>guard(()=>{if(!S.selectedRow)throw new Error('Select a complete original row.');download(S.selectedRow,'Accounting_Return_Selected_Row.json');}));
$('open-current').addEventListener('click',()=>guard(()=>openComparison(S.detail.id)));
$('refresh-comparison').addEventListener('click',()=>guard(refreshComparison));
$('recover-request').addEventListener('click',()=>guard(recoverOriginal));
$('retry-request').addEventListener('click',()=>guard(()=>{if(S.pending)return sendOriginal(S.pending);}));
$('download-request').addEventListener('click',()=>guard(()=>{if(S.pending)download(S.pending,'Accounting_Return_Request_'+S.pending.id+'.json');}));
onForm('capture-form',captureOriginal);onForm('mapping-form',event=>saveMapping(event.submitter?.value==='confirm'));
onForm('comparison-form',createComparison);onForm('assignment-form',assignRow);onForm('retire-assignment-form',retireAssignment);onForm('finding-form',reviewFinding);onForm('decision-form',decide);onForm('packet-form',packet);
async function start(){S.db=await dbOpen();await refresh({reopen:false});const owner=await get('drafts',key('operator'));$('operator-name').value=owner??'';const pendingId=await get('drafts',key('pending'));if(pendingId)S.pending=await get('requests',key(pendingId));const view=await get('drafts',key('view'));if(view?.export_id&&S.state.exports.some(e=>e.id===view.export_id))await selectExport(view.export_id,{retain:false});else if(S.state.exports.length===1)await selectExport(S.state.exports[0].id,{retain:false});else renderExport();if(view?.receiving_id&&S.state.runs.some(r=>r.id===view.receiving_id))await openComparison(view.receiving_id,view.edition_id??null,{retain:false});renderPending();await renderRequestHistory();controls();document.documentElement.dataset.receivingReady='true';if(S.pending)status('An original request is retained. Read its result to continue the same receiving operation.');}
controls();
start().catch(error=>{document.documentElement.dataset.receivingReady='error';status(error.message);});

function inspectOriginal(row,title){let dialog=$('original-row-dialog');if(!dialog){dialog=document.createElement('dialog');dialog.id='original-row-dialog';document.body.append(dialog);}dialog.replaceChildren();dialog.append(element('h2',title),element('pre',nice(row)));const actions=element('div',undefined,'actions');actions.append(button('Download complete original row',()=>download(row,'Original_Returned_Row.json')),button('Close',()=>dialog.close()));dialog.append(actions);dialog.showModal();}
